const Pelusa = mk("iris", false, (tt) => { const cl2 = tt < 2.2 ? W(tt, 0.4, 1.8) : 1 - W(tt, 2.4, 3.6); return <g><Plas x={340} y={140} w={1240} h={780} /><Grille x={960} y={480} w={620} h={360} clog={cl2} /><g transform={`translate(${lp(1700, 1320, W(tt, 2, 2.6))},${480 + 70 * Math.sin(tt * 4)})`}><rect x={0} y={-52} width={500} height={104} rx={18} fill="#555" /><rect x={-40} y={-90} width={60} height={180} rx={10} fill="#333" /></g></g>; }, (tt) => <Lbl tt={tt} at={1.3} x={960} y={830} tx="TAPADA NO RESPIRA" bg={RED} col={INK} />);
const Dedos = mk("ring", false, (tt) => <g><Ground y={840} />{[0, 1].map((i) => <g key={i} transform={`translate(${i ? 1040 : 280},${(1 - P(tt, 0.3 + i * 0.5)) * 300})`}><rect width={600} height={420} y={420} fill={i ? "#d8c9a4" : "#c8d7c0"} stroke="#3a2a1a" strokeWidth={6} /><path d="M -40 420 L 300 200 L 640 420 Z" fill={BRICK} stroke="#3a2a1a" strokeWidth={6} /></g>)}<rect x={880} y={420} width={160} height={420} fill="url(#brick)" stroke="#3a2a1a" strokeWidth={6} /><Arrow x1={760} y1={120} x2={1130} y2={120} k={W(tt, 1.4, 2.2)} /><Arrow x1={1160} y1={190} x2={790} y2={190} k={W(tt, 2.2, 3)} /></g>, (tt) => <Lbl tt={tt} at={3} x={960} y={970} tx="SE CUIDAN DE A DOS" bg={AMB} />);
const RP = [["DIAGNÓSTICO", "nailon 48 h"], ["VECINO", "con un mate"], ["SACAR", "en seco"], ["SECAR", "con paciencia"], ["REVOCAR", "que respire"], ["CONTRATABIQUE", "con rejillas"], ["TERMINAR", "látex y aire"]];
const Repaso = mk("wipe", false, (tt) => <g>{RP.map(([a, b], i) => { const col = i < 4 ? 0 : 1, row = col ? i - 4 : i, x = col ? 1400 : 540, y = 210 + row * 215 + (col ? 100 : 0); return <Card key={i} x={x} y={y} w={800} h={186} s={P(tt, 0.2 + i * 0.58)} bg={i === 5 ? AMB : INK} rot={i % 2 ? 1 : -1}><T x={-330} y={32} tx={String(i + 1)} size={110} col={RED} /><T x={60} y={-8} tx={a} size={44} /><T x={60} y={56} tx={b} size={50} hand col="#5a4a36" /></Card>; })}</g>);
const Tomates = mk("split", false, (tt) => { const k = (tt * 0.45) % 1; return <g><Ground y={860} /><rect x={120} y={560} width={1680} height={300} fill="url(#brick)" stroke="#3a2a1a" strokeWidth={6} /><Planter x={1140} y={640} w={500} h={220} />{[0, 0.33, 0.66].map((o, i) => { const q = (k + o) % 1; return <circle key={i} cx={lp(1320, 620, q)} cy={560 - 340 * Math.sin(q * Math.PI)} r={44} fill="#d6382a" stroke="#7a1a10" strokeWidth={5} />; })}</g>; }, (tt) => <><Lbl tt={tt} at={2} x={1400} y={960} tx="LA NUEVA, A 10 CM" bg={AMB} /><Lbl tt={tt} at={3.1} x={560} y={960} tx="SE ARREGLÓ EL BARRIO" hand bg={INK} /></>);

